#!/usr/bin/env python3
# Generado por herramientas/proteger_codigo.py a partir de sipi_ia.py -- no editar a mano.
# Este archivo es un loader: el codigo real esta compilado a bytecode
# de Python y codificado abajo, no como texto plano. Se ejecuta
# exactamente igual que el original ('python3 sipi_ia.py [argumentos]').
import marshal, base64, sys, os

# IMPORTANTE: __file__ tiene que apuntar a la ubicacion REAL de ESTE
# archivo protegido (no al nombre del .py original) -- el codigo de
# SiPi usa os.path.dirname(os.path.abspath(__file__)) para encontrar
# recursos relativos (iconos, el motor de SiPi, etc). Si aca se pusiera
# el nombre del original a secas, esa busqueda se resolveria contra el
# directorio de trabajo actual en vez del directorio de instalacion
# real, y esos recursos no se encontrarian una vez instalado el
# paquete (por ejemplo, los iconos de la barra de herramientas
# quedarian invisibles pese a estar presentes en el disco).
_ruta_real = os.path.abspath(__file__)

_bytecode = base64.b64decode('')
_codigo = marshal.loads(_bytecode)
sys.argv[0] = _ruta_real
# IMPORTANTE: ejecutar contra globals() (el namespace real de ESTE
# modulo/script), no contra un diccionario temporal aparte. Si se usara
# un dict nuevo, las funciones/clases del codigo original quedarian
# atrapadas ahi adentro y serian invisibles para quien haga
# 'import este_archivo_protegido' -- el atributo no existiria en el
# modulo pese a que el codigo se ejecuto sin error. Usando globals():
#  - Si el archivo se corre directo ('python3 archivo.py'), __name__
#    ya vale '__main__' de forma natural, igual que el original.
#  - Si se importa ('import archivo'), __name__ vale el nombre del
#    modulo, tambien igual que el original -- asi que un
#    'if __name__ == "__main__":' adentro del codigo protegido se
#    comporta exactamente igual protegido que sin proteger.
exec(_codigo, globals())
